<?php
declare(strict_types=1);
function stripe(string $path,array $data=[],string $method='POST'):array{$c=config();if(empty($c['stripe_secret']))fail('Payment processing is not configured',503);$ch=curl_init('https://api.stripe.com/v1/'.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>25,CURLOPT_USERPWD=>$c['stripe_secret'].':',CURLOPT_HTTPHEADER=>['Stripe-Version: 2024-06-20']]);if($method==='POST')curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($data)]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);$body=json_decode($raw?:'',true);if(!$body||$code>=400)throw new RuntimeException('Payment provider request failed');return $body;}
function billing(string $action,array $u,array $b):never{if(!in_array($u['role'],['owner','admin']))fail('Only a workspace owner can manage billing',403);$w=query('SELECT * FROM workspaces WHERE id=?',[$u['workspace']])->fetch();$url=rtrim(config()['app_url'],'/').'/index.php?view=workspace';if($action==='billing_portal'){if(!$w['customer'])fail('No billing customer is linked yet');$r=stripe('billing_portal/sessions',['customer'=>$w['customer'],'return_url'=>$url]);respond(['url'=>$r['url']]);}if(in_array($w['subscription_status'],['active','trialing','past_due']))fail('Manage your existing subscription through the billing portal.');$plan=$b['plan']??'';$price=config()['stripe_prices'][$plan]??'';if(!$price)fail('This plan is not configured');$data=['mode'=>'subscription','line_items'=>[['price'=>$price,'quantity'=>1]],'success_url'=>$url.'&billing=success','cancel_url'=>$url.'&billing=cancelled','client_reference_id'=>$w['id'],'subscription_data'=>['metadata'=>['workspace'=>$w['id'],'plan'=>$plan]]];if($w['customer'])$data['customer']=$w['customer'];else $data['customer_email']=$u['email'];$r=stripe('checkout/sessions',$data);respond(['url'=>$r['url']]);}
function webhook():never{$secret=config()['stripe_webhook_secret']??'';if(!$secret)fail('Webhook is not configured',503);$raw=file_get_contents('php://input');if(strlen($raw)>1000000)fail('Too large',413);$parts=explode(',',$_SERVER['HTTP_STRIPE_SIGNATURE']??'');$t=0;$sigs=[];foreach($parts as $part){[$k,$v]=array_pad(explode('=',$part,2),2,'');if($k==='t')$t=(int)$v;if($k==='v1')$sigs[]=$v;}$expected=hash_hmac('sha256',$t.'.'.$raw,$secret);$valid=false;foreach($sigs as $sig)if(hash_equals($expected,$sig))$valid=true;if(!$valid||abs(time()-$t)>300)fail('Invalid signature',400);$event=json_decode($raw,true);if(!$event||empty($event['id']))fail('Invalid event');if(query('SELECT id FROM events WHERE id=?',[$event['id']])->fetch())respond(['received'=>true]);$obj=$event['data']['object']??[];$type=$event['type']??'';
// Retrieve current state to avoid applying out-of-order subscription events.
if($type==='checkout.session.completed'||str_starts_with($type,'customer.subscription.')){$sid=$type==='checkout.session.completed'?($obj['subscription']??''):($obj['id']??'');if($sid){$sub=stripe('subscriptions/'.rawurlencode($sid),[],'GET');$wid=$sub['metadata']['workspace']??'';$price=$sub['items']['data'][0]['price']['id']??'';$plan=array_search($price,config()['stripe_prices'],true);if($wid&&$plan!==false){query('UPDATE workspaces SET customer=?,subscription_status=?,plan=? WHERE id=?',[$sub['customer'],$sub['status'],$plan,$wid]);}}}try{query('INSERT INTO events (id,created) VALUES (?,?)',[$event['id'],now()]);}catch(PDOException $e){if(!query('SELECT id FROM events WHERE id=?',[$event['id']])->fetch())throw $e;}respond(['received'=>true]);}
